import sys

data = list(map(int, sys.stdin.buffer.read().split()))
L, C = data[0], data[1]
P = data[2]

black = set()
idx = 3
for _ in range(P):
    x, y = data[idx] - 1, data[idx + 1] - 1
    idx += 2
    black.add((x, y))

candidates = set()
for x, y in black:
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nx, ny = x + dx, y + dy
        if 0 <= nx < L and 0 <= ny < C and (nx, ny) not in black:
            candidates.add((nx, ny))

adj = {}
for x, y in candidates:
    if (x + y) % 2 == 0:
        adj[(x, y)] = [
            (x + dx, y + dy)
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))
            if (x + dx, y + dy) in candidates
        ]

matched = {}
def augment(cell, seen):
    for neighbor in adj[cell]:
        if neighbor in seen:
            continue
        seen.add(neighbor)
        if neighbor not in matched or augment(matched[neighbor], seen):
            matched[neighbor] = cell
            return True
    return False

matching = sum(augment(cell, set()) for cell in adj)
print(len(candidates) - matching)
